'use strict';
const workspace=document.getElementById('admin-workspace'),dialog=document.getElementById('admin-dialog'),content=document.getElementById('admin-dialog-content');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const time=v=>new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(v);
let item,caseItem,screen;
function resetReview(){item={title:'微单相机与定焦镜头',status:'待审核',version:3,submittedAt:Date.now()-35*60000,result:null,history:[{decision:'驳回',at:Date.now()-86400000,by:'何管理员',reason:'商品描述未说明配件是否齐全，请补充后重新送审。',version:1}]};}
function resetCase(){const sample=document.getElementById('violation-sample').value;const states={confirmed:['已确认','已确认'],waiting:['已预约','待卖家确认'],none:['已发布',null],completed:['已完成','已完成']};const p=states[sample];caseItem={status:p[0],reservationStatus:p[1],oldStatus:p[0],oldReservation:p[1],handled:false,reason:'',hidden:false,at:null};}
function heading(title,sub,status=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div>${status?`<span class="status">${esc(status)}</span>`:''}</div>`;}
function productCard(status){return `<div class="admin-detail"><img src="assets/camera.jpg" alt="相机商品示意照片"><div><div class="eyebrow"><span>商品 P20261109-001 · 数码电子</span><span class="status">${esc(status)}</span></div><h2>微单相机与定焦镜头</h2><div class="price">¥1,680</div><dl><div><dt>卖家</dt><dd>陈同学</dd></div><div><dt>交付地点</dt><dd>仙林校区 · 图书馆东门</dd></div><div><dt>图片</dt><dd>1 张 · 原型示意图</dd></div><div><dt>当前信息</dt><dd>仅供审核查看，不能代改</dd></div></dl></div></div>`;}
function history(){return `<section class="admin-card"><h2>审核历史 <span style="font-size:12px;color:var(--muted)"> / 每次审核独立保留</span></h2><ul class="history">${item.history.slice().reverse().map(h=>`<li><div class="history-top"><strong>${esc(h.decision)}${h.decision==='通过'?' · 商品已发布':' · 退回草稿'}</strong><span>${time(h.at)} · ${esc(h.by)}</span></div>${h.reason?`<p>原因：${esc(h.reason)}</p>`:'<p>审核通过，商品可以公开展示并接受预约。</p>'}<small>审核商品版本 v${h.version}</small></li>`).join('')}</ul></section>`;}
function list(){workspace.innerHTML=heading('待审核商品','核对商品内容，让每件闲置合规上架。')+`<section class="admin-card"><div class="list-toolbar"><span>待审核 <strong>${item.status==='待审核'?1:0}</strong> 件</span><span>按提交时间排列 · 模拟数据</span></div>${item.status==='待审核'?`<table class="review-table"><thead><tr><th>商品</th><th>卖家</th><th class="optional">提交时间</th><th>状态</th><th>操作</th></tr></thead><tbody><tr><td><div class="table-product"><img src="assets/camera.jpg" alt="相机商品示意图"><div><strong>${esc(item.title)}</strong><small>¥1,680 · 数码电子</small></div></div></td><td>陈同学</td><td class="optional">${time(item.submittedAt)}</td><td><span class="status">待审核</span></td><td><a class="text-link" href="#review">查看审核 →</a></td></tr></tbody></table>`:`<div class="empty-list">当前没有待审核商品。<br><a class="text-link" href="#review">查看刚才处理的商品及历史 →</a></div>`}</section><div class="rule-box"><strong>审核范围</strong>管理员可通过或驳回商品，不能修改卖家填写的价格、标题等业务字段。审核通过不代表平台担保商品真实性或线下交付。</div>`;}
function reviewDetail(){const pending=item.status==='待审核';workspace.innerHTML=heading('商品审核详情','查看当前送审内容，并作出明确的审核决定。',item.status)+`<section class="admin-card">${productCard(item.status)}<div class="detail-description"><h2>卖家描述</h2><p>记录校园生活用的相机，机身和镜头正常工作，有轻微使用痕迹。附电池、充电器及相机背带，可当面检查。具体交付时间在预约确认后协商。</p></div>${!pending?`<div class="${item.result?'result-banner':'readonly-message'}">${item.result?`<strong>审核${item.result.decision} · 商品${item.status==='已发布'?'已发布':'已退回草稿'}</strong><p>${item.result.reason?`驳回原因：${esc(item.result.reason)}`:'审核记录已保留，商品现可接受预约。'}</p>`:'商品已被卖家撤回为草稿，本次审核入口已关闭。请返回列表查看最新待审核商品。'}</div>`:''}<div class="admin-actions"><p>送审版本 v${item.version} · ${time(item.submittedAt)} 提交<br>审核前会再次核对当前状态与版本。</p><div><button class="btn secondary" data-decision="驳回" ${pending?'':'disabled'}>填写原因并驳回</button><button class="btn primary" data-decision="通过" ${pending?'':'disabled'}>通过审核</button></div></div></section>${history()}<a class="text-link" href="#reviews">← 返回待审核列表</a>`;}
function reservationBlock(c){return `<section class="association"><div class="association-head"><h3>${c.reservationStatus?'关联预约':'关联有效预约'}</h3><span class="status">${c.reservationStatus?esc(c.reservationStatus):'无有效预约'}</span></div>${c.reservationStatus?`<div class="data-row"><span>预约编号</span><strong>R20261109-001</strong></div><div class="data-row"><span>交易双方</span><strong>林同学（买家） / 陈同学（卖家）</strong></div><div class="data-row"><span>预约价格快照</span><strong>¥1,680</strong></div><div class="data-row"><span>处置影响</span><strong>${c.status==='已完成'?'保留已完成状态及交易历史':c.handled?'有效预约已终止，历史快照保留':'违规下架时同步终止'}</strong></div>`:'<p class="result-note">当前没有待卖家确认或已确认的预约，只需处置商品并通知卖家。</p>'}</section>`;}
function violationPage(){const c=caseItem;if(c.handled){violationResult();return;}workspace.innerHTML=heading('违规下架','确认违规事实并说明原因，保留完整处理记录。')+`<div class="warning-panel"><strong>${c.status==='已完成'?'已完成交易仅作历史违规处置':'本次处理将影响商品与关联预约'}</strong><p>${c.status==='已完成'?'商品与预约的已完成状态不会改变，仅追加违规记录并隐藏公开内容。':'商品将变为违规下架，停止展示和预约；待卖家确认或已确认的关联预约将同步终止。无需以双方同意为前提。'}</p></div><section class="admin-card">${productCard(c.status)}${reservationBlock(c)}<form id="violation-form" novalidate><div class="field"><label for="violation-reason">违规原因 <small>必填 · 将记录在处置历史中</small></label><textarea id="violation-reason" placeholder="请说明核实到的违规事实与下架依据" aria-describedby="violation-error"></textarea><span class="field-error" id="violation-error" role="alert"></span><p class="field-hint">请填写具体原因，不要录入密码或完整联系方式。</p></div><div class="admin-actions"><p>处理人：周管理员<br>商品、预约、日志和待发送通知将一并保存。</p><div><button type="submit" class="btn danger">${c.status==='已完成'?'记录违规并隐藏商品':'确认违规下架'}</button></div></div></form></section>`;}
function violationResult(){const c=caseItem;workspace.innerHTML=heading('违规处置结果','商品及关联记录已完成本次模拟处理。')+`<section class="admin-card"><div class="result-heading"><span class="result-check" aria-hidden="true">✓</span><div><h2 class="review-result-title">${c.status==='已完成'?'违规已记录，商品已隐藏':'违规下架已完成'}</h2><span class="result-note">处理人：周管理员 · ${time(c.at)}（北京时间）</span></div></div><ul class="result-list"><li><span>商品状态</span><strong>${esc(c.oldStatus)} ${c.oldStatus===c.status?'（保持不变）':'→ '+esc(c.status)}</strong></li><li><span>公开展示与新预约</span><strong>已隐藏，不接受新预约</strong></li><li><span>关联预约</span><strong>${c.oldReservation?`${esc(c.oldReservation)} ${c.oldReservation===c.reservationStatus?'（保持不变）':'→ '+esc(c.reservationStatus)}`:'无有效预约，无需终止'}</strong></li><li><span>历史记录与交易快照</span><strong>完整保留</strong></li><li><span>处置记录与操作日志</span><strong>已记录</strong></li><li><span>站内通知</span><strong>待发送记录已保存</strong></li></ul><p class="result-note">通知对象：${c.oldReservation?'买卖双方':'卖家'}。通知提交后投递，发送失败不撤销已完成的处置。</p><div class="reason-display"><span>违规原因</span><p>${esc(c.reason)}</p></div><div class="notice-inline">${c.status==='已完成'?'已完成交易未被终止，商品与预约仍保持已完成。':'原有效预约已终止；买家取消等旧操作不能使违规商品恢复已发布。'}</div><div class="admin-actions"><p>本次处理已结束，不能重复提交。</p><button type="button" class="btn secondary" id="show-case">查看处置商品与关联记录</button></div></section>`;}
function render(){if(dialog.open)dialog.close();screen=location.hash.startsWith('#figmacapture=')?new URLSearchParams(location.search).get('view'):location.hash.slice(1);if(!['reviews','review','violation'].includes(screen))screen='reviews';document.querySelectorAll('[data-page]').forEach(a=>a.dataset.page===screen?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current'));document.querySelectorAll('[data-nav]').forEach(a=>(a.dataset.nav===(screen==='violation'?'violation':'reviews'))?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current'));document.getElementById('admin-crumb').textContent={reviews:'待审核列表',review:'审核详情',violation:'违规下架'}[screen];document.getElementById('violation-sample').hidden=screen!=='violation';document.getElementById('simulate-withdraw').hidden=screen!=='review';document.title=document.getElementById('admin-crumb').textContent+' · 校园集';({reviews:list,review:reviewDetail,violation:violationPage}[screen])();}
function openReview(decision){const expectedVersion=item.version;content.innerHTML=`<div class="modal-top"><span class="modal-overline">审核决定</span><button class="close" data-close aria-label="关闭">×</button></div><h2 class="modal-title" id="admin-dialog-title">${decision==='通过'?'确认通过审核？':'填写驳回原因'}</h2><p class="modal-copy">${decision==='通过'?'商品将转为已发布，对用户公开并接受预约。':'商品将退回草稿，卖家根据原因修改后可重新送审。'}</p>${decision==='驳回'?'<div class="field"><label for="review-reason">驳回原因 <small>必填</small></label><textarea id="review-reason" placeholder="请说明需要补充或修正的具体内容" aria-describedby="review-error"></textarea></div>':''}<span id="review-error" class="field-error" role="alert"></span><div class="modal-actions" style="margin-top:24px"><button class="btn secondary" data-close>暂不处理</button><button class="btn primary" data-review-submit="${decision}" data-version="${expectedVersion}">${decision==='通过'?'确认通过':'确认驳回'}</button></div>`;dialog.showModal();}
function notify(message){const toast=document.getElementById('toast');toast.textContent=message;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),3000);}
document.addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;if(button.dataset.decision){if(item.status!=='待审核'){notify('商品状态已变化，请刷新列表。');return;}openReview(button.dataset.decision);}if(button.hasAttribute('data-close'))dialog.close();if(button.dataset.reviewSubmit){const reason=document.getElementById('review-reason'),decision=button.dataset.reviewSubmit,result=AdminRules.review(item.status,decision,reason?.value||'');if(Number(button.dataset.version)!==item.version)result.error='商品版本已变化，请关闭窗口后重新检查。';if(result.error){document.getElementById('review-error').textContent=result.error;if(reason){reason.setAttribute('aria-invalid','true');reason.focus();}return;}const record={decision,reason:reason?.value.trim()||'',by:'周管理员',at:Date.now(),version:item.version};item.status=result.status;item.history.push(record);item.result=record;item.version++;dialog.close();reviewDetail();}if(button.id==='simulate-withdraw'){if(item.status!=='待审核'){notify('当前商品已处理，请先重置示例。');return;}item.status='草稿';item.version++;reviewDetail();}if(button.id==='reset-admin'){resetReview();resetCase();render();}if(button.id==='show-case'){workspace.innerHTML=heading('已处置商品','只读查看，本次处置已结束。',caseItem.status)+`<section class="admin-card">${productCard(caseItem.status)}${reservationBlock(caseItem)}<div class="reason-display"><span>违规原因</span><p>${esc(caseItem.reason)}</p></div><p class="readonly-message">商品已隐藏。此处是管理员只读视图，不代表商品仍向公众展示。</p><button class="btn secondary" id="back-result">返回处置结果</button></section>`;}if(button.id==='back-result')violationResult();});
document.addEventListener('submit',e=>{if(e.target.id!=='violation-form')return;e.preventDefault();const field=document.getElementById('violation-reason'),result=AdminRules.violation(caseItem.status,caseItem.reservationStatus,field.value);if(caseItem.handled)result.error='本次处置已完成，请勿重复提交。';if(result.error){document.getElementById('violation-error').textContent=result.error;field.setAttribute('aria-invalid','true');field.focus();return;}caseItem={...caseItem,status:result.productStatus,reservationStatus:result.reservationStatus,hidden:result.hidden,reason:field.value.trim(),handled:true,at:Date.now()};violationResult();});
document.getElementById('violation-sample').addEventListener('change',()=>{resetCase();violationPage();});window.addEventListener('hashchange',render);if(new URLSearchParams(location.search).has('capture'))document.body.classList.add('capture');resetReview();resetCase();render();
